.selection-evidence{flex:none;max-height:32%;overflow:auto;padding:12px 18px;border-top:1px solid var(--line);background:var(--surface);color:var(--text);font-size:12px;line-height:1.5;min-width:0}
.selection-evidence p{margin:5px 0;overflow-wrap:anywhere}.selection-heading{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-bottom:6px}.selection-heading strong{font-size:14px}
.selection-source{font-size:10px;color:var(--muted)}.property-basis{font-size:11px;color:var(--muted)}.provenance-tag{font-size:10px;border:1px solid var(--line);border-radius:4px;padding:2px 5px;color:var(--accent);font-weight:500}
.evidence-property{padding:7px 0;border-top:1px solid var(--line)}.evidence-property-heading{display:flex;gap:8px;align-items:baseline;justify-content:space-between}.evidence-property strong{font-size:12px}.selected-property-details>summary{cursor:pointer;font-weight:600;margin:8px 0}
