.provenance-legend{margin-top:8px;color:var(--muted)}.provenance-legend summary{cursor:pointer;color:var(--text)}.provenance-legend[open]{max-height:170px;overflow:auto}.provenance-legend dl{display:grid;grid-template-columns:130px 1fr;gap:6px;margin:9px 0}.provenance-legend dt{font-weight:600;color:var(--text)}.provenance-legend dd{margin:0}.provenance-legend p{line-height:1.5}
